package io.fireflysoftware.experience.insurance.web.policies.impl;

import io.fireflysoftware.domain.insurance.policies.sdk.invoker.ApiClient;
import io.fireflysoftware.experience.insurance.core.journey.policies.*;
import io.fireflysoftware.experience.insurance.core.journey.policies.impl.GovernedPolicyJourneyServiceImpl;
import io.fireflysoftware.experience.insurance.web.policies.GovernedPolicyDomainClientFactory;
import java.io.IOException;
import java.net.URI;
import java.time.Duration;
import java.time.LocalDate;
import java.util.*;
import java.util.concurrent.CopyOnWriteArrayList;
import org.junit.jupiter.api.Test;
import org.springframework.http.HttpStatus;
import org.springframework.http.MediaType;
import org.springframework.http.client.reactive.*;
import org.springframework.mock.http.client.reactive.*;
import org.springframework.web.server.ResponseStatusException;
import reactor.core.publisher.Mono;
import reactor.test.StepVerifier;
import static org.junit.jupiter.api.Assertions.*;

class GeneratedGovernedPolicyDomainPortTest {
    static final String DIGEST="a".repeat(64),CALLER="current-human";
    GovernedPolicyBindRequest request(){return new GovernedPolicyBindRequest(UUID.randomUUID(),UUID.randomUUID(),UUID.randomUUID(),UUID.randomUUID(),UUID.randomUUID(),1,1,UUID.randomUUID(),DIGEST,DIGEST,UUID.randomUUID(),"SANDBOX-1",LocalDate.of(2027,1,1),LocalDate.of(2028,1,1));}
    record Sent(String path,String body,String bearer){}
    static final class FactoryFixtureImpl implements GovernedPolicyDomainClientFactory {
        final List<Sent> sent=new CopyOnWriteArrayList<>();String prepareResponse,commandResponse,recoveryResponse;HttpStatus prepareStatus=HttpStatus.OK,commandStatus=HttpStatus.OK;boolean losePrepare,loseCommand,revokeAfterPrepare,revokeAfterCommand;final List<String> callers=new CopyOnWriteArrayList<>();
        @Override public Mono<Client> current(GovernedPolicyDomainPort.Action action){return Mono.deferContextual(context->{String caller=context.get(CALLER);callers.add(caller);return Mono.just(new Client(){boolean revoked;
            @Override public URI endpoint(){return URI.create("https://synthetic-domain.invalid");}
            @Override public String bearerToken(){return caller;}
            @Override public Duration remaining(){return Duration.ofSeconds(2);}
            @Override public Mono<Void> revalidate(){return Mono.deferContextual(current->!revoked && caller.equals(current.getOrDefault(CALLER,""))?Mono.empty():Mono.error(new ResponseStatusException(HttpStatus.FORBIDDEN)));}
            @Override public ClientHttpConnector connector(){return (method,uri,callback)->{var request=new MockClientHttpRequest(method,uri);return callback.apply(request).then(Mono.defer(request::getBodyAsString)).flatMap(body->{String path=uri.getPath();sent.add(new Sent(path,body,request.getHeaders().getFirst("Authorization")));boolean prepare=path.endsWith("/governed/intents");if(prepare && losePrepare || !prepare && loseCommand)return Mono.error(new IOException("controlled possible transport loss"));var response=new MockClientHttpResponse(prepare?prepareStatus:commandStatus);response.getHeaders().setContentType(MediaType.APPLICATION_JSON);response.setBody(prepare?prepareResponse:path.contains("/recovery/")?recoveryResponse:commandResponse);if(prepare && revokeAfterPrepare || !prepare && revokeAfterCommand)revoked=true;return Mono.just((ClientHttpResponse)response);});};}
        });});}
    }
    <T> Mono<T> caller(Mono<T> work,String caller){return work.contextWrite(context->context.put(CALLER,caller));}
    String prepared(UUID action,String operation){return "{\"operation\":\""+operation+"\",\"actionId\":\""+action+"\",\"intentDigest\":\""+DIGEST+"\"}";}
    String command(UUID action){return "{\"status\":\"OUTCOME_UNKNOWN\",\"actionId\":\""+action+"\",\"intentDigest\":\""+DIGEST+"\"}";}
    GovernedPolicyJourneyServiceImpl service(FactoryFixtureImpl factory){return new GovernedPolicyJourneyServiceImpl(new GeneratedGovernedPolicyDomainPortImpl(factory));}
    @Test void actualGeneratedPreparationAndOneBindKeepTheSameRequestActionDigestAndBearer(){var f=new FactoryFixtureImpl();var r=request();f.prepareResponse=prepared(r.actionId(),"BIND");f.commandResponse=command(r.actionId());StepVerifier.create(caller(service(f).bind(r),"human-A")).assertNext(value->{assertEquals(r.actionId(),value.actionId());assertEquals(DIGEST,value.intentDigest());}).verifyComplete();assertEquals(2,f.sent.size());assertEquals("/api/v1/policies/governed/intents",f.sent.getFirst().path());assertEquals("/api/v1/policies/governed/bindings",f.sent.getLast().path());assertEquals(List.of("human-A"),f.callers);assertEquals("Bearer human-A",f.sent.getFirst().bearer());assertEquals(f.sent.getFirst().bearer(),f.sent.getLast().bearer());assertDoesNotThrow(()->{var mapper=ApiClient.createDefaultMapper(null);var prep=mapper.readTree(f.sent.getFirst().body());assertEquals("BIND",prep.path("operation").asText());assertEquals(mapper.readTree(f.sent.getLast().body()),prep.path("bindRequest"));assertTrue(prep.path("issueRequest").isMissingNode() || prep.path("issueRequest").isNull());assertTrue(prep.path("policyId").isMissingNode() || prep.path("policyId").isNull());});}
    @Test void actualGeneratedIssuePreparationKeepsTheExistingPolicyAndThreeSelectors(){var f=new FactoryFixtureImpl();var policy=UUID.randomUUID();var r=new GovernedPolicyIssueRequest(UUID.randomUUID(),1,DIGEST);f.prepareResponse=prepared(r.actionId(),"ISSUE");f.commandResponse=command(r.actionId());StepVerifier.create(caller(service(f).issue(policy,r),"human-A")).expectNextCount(1).verifyComplete();assertEquals(2,f.sent.size());assertEquals("/api/v1/policies/"+policy+"/governed/issue",f.sent.getLast().path());assertDoesNotThrow(()->{var mapper=ApiClient.createDefaultMapper(null);var prep=mapper.readTree(f.sent.getFirst().body());assertEquals("ISSUE",prep.path("operation").asText());assertEquals(policy.toString(),prep.path("policyId").asText());assertEquals(mapper.readTree(f.sent.getLast().body()),prep.path("issueRequest"));assertTrue(prep.path("bindRequest").isMissingNode() || prep.path("bindRequest").isNull());});}
    @Test void lostReadOnlyPreparationCannotDispatchOrBecomeAnUnknownMutation(){var f=new FactoryFixtureImpl();f.losePrepare=true;StepVerifier.create(caller(service(f).bind(request()),"human-A")).expectErrorSatisfies(error->{assertInstanceOf(ResponseStatusException.class,error);assertFalse(error instanceof GovernedPolicyOutcomeUnknownException);}).verify();assertEquals(1,f.sent.size());assertTrue(f.sent.getFirst().path().endsWith("/intents"));}
    @Test void anotherPreparedActionOrOperationCannotStartTheMutation(){for(var wrong:List.of(prepared(UUID.randomUUID(),"BIND"),prepared(UUID.randomUUID(),"ISSUE"))){var f=new FactoryFixtureImpl();f.prepareResponse=wrong;StepVerifier.create(caller(service(f).bind(request()),"human-A")).expectError(ResponseStatusException.class).verify();assertEquals(1,f.sent.size());}}
    @Test void authorityLostAfterPreparationCannotDispatchTheCommand(){var f=new FactoryFixtureImpl();var r=request();f.prepareResponse=prepared(r.actionId(),"BIND");f.revokeAfterPrepare=true;StepVerifier.create(caller(service(f).bind(r),"human-A")).expectErrorSatisfies(error->assertEquals(HttpStatus.FORBIDDEN,((ResponseStatusException)error).getStatusCode())).verify();assertEquals(1,f.sent.size());}
    @Test void aCallerBoundHandleCannotSubstituteSelectorsAfterPreparation(){var f=new FactoryFixtureImpl();var r=request();f.prepareResponse=prepared(r.actionId(),"BIND");var port=new GeneratedGovernedPolicyDomainPortImpl(f);StepVerifier.create(caller(port.current(GovernedPolicyDomainPort.Action.BIND).flatMap(client->client.prepareBind(r).then(client.bind(request()))),"human-A")).expectErrorSatisfies(error->assertEquals(HttpStatus.CONFLICT,((ResponseStatusException)error).getStatusCode())).verify();assertEquals(1,f.sent.size());}
    @Test void aCallerBoundHandleCannotDispatchASecondMutation(){var f=new FactoryFixtureImpl();var r=request();f.prepareResponse=prepared(r.actionId(),"BIND");f.commandResponse=command(r.actionId());var port=new GeneratedGovernedPolicyDomainPortImpl(f);StepVerifier.create(caller(port.current(GovernedPolicyDomainPort.Action.BIND).flatMap(client->client.prepareBind(r).then(client.bind(r)).then(client.bind(r))),"human-A")).expectErrorSatisfies(error->assertEquals(HttpStatus.CONFLICT,((ResponseStatusException)error).getStatusCode())).verify();assertEquals(2,f.sent.size());}
    @Test void uncertainMutationKeepsThePreparedOwnerDigestWithoutAnotherCommand(){var f=new FactoryFixtureImpl();var r=request();f.prepareResponse=prepared(r.actionId(),"BIND");f.loseCommand=true;StepVerifier.create(caller(service(f).bind(r),"human-A")).assertNext(value->{assertEquals(GovernedPolicyCommandResponse.Status.OUTCOME_UNKNOWN,value.status());assertEquals(r.actionId(),value.actionId());assertEquals(DIGEST,value.intentDigest());assertNull(value.result());}).verifyComplete();assertEquals(2,f.sent.size());}
    @Test void recoveryUsesOnlyTheOriginalGeneratedReadWithoutPreparationOrMutation(){var f=new FactoryFixtureImpl();var action=UUID.randomUUID();f.recoveryResponse="{\"state\":\"NOT_OBSERVED_AT_THIS_READ\",\"actionId\":\""+action+"\",\"intentDigest\":\""+DIGEST+"\"}";StepVerifier.create(caller(service(f).recover(action,DIGEST),"human-A")).assertNext(value->assertEquals(GovernedPolicyRecoveryResponse.State.NOT_OBSERVED_AT_THIS_READ,value.state())).verifyComplete();assertEquals(1,f.sent.size());assertEquals("/api/v1/policies/governed/recovery/"+action,f.sent.getFirst().path());}
    @Test void overlappingHumansKeepSeparatePreparationAndGeneratedCommands(){var f=new FactoryFixtureImpl();var r=request();f.prepareResponse=prepared(r.actionId(),"BIND");f.commandResponse=command(r.actionId());StepVerifier.create(Mono.zip(caller(service(f).bind(r),"human-A"),caller(service(f).bind(r),"human-B"))).expectNextCount(1).verifyComplete();assertEquals(4,f.sent.size());assertEquals(Set.of("human-A","human-B"),Set.copyOf(f.callers));for(String bearer:List.of("Bearer human-A","Bearer human-B")){var own=f.sent.stream().filter(sent->bearer.equals(sent.bearer())).toList();assertEquals(2,own.size());assertTrue(own.getFirst().path().endsWith("/intents"));assertTrue(own.getLast().path().endsWith("/bindings"));}}
    String committed(GovernedPolicyBindRequest request){return "{\"status\":\"COMMITTED\",\"actionId\":\""+request.actionId()+"\",\"intentDigest\":\""+DIGEST+"\",\"result\":{\"policyId\":\""+UUID.randomUUID()+"\",\"policyNumber\":\"SANDBOX-1\",\"policyStatus\":\"BOUND\",\"bindingVersion\":1,\"bindingReceiptDigest\":\""+DIGEST+"\",\"acceptanceActionId\":\""+request.acceptanceActionId()+"\",\"acceptanceId\":\""+UUID.randomUUID()+"\",\"offerId\":\""+request.offerId()+"\",\"offerVersion\":1,\"termsDigest\":\""+DIGEST+"\"}}";}
    @Test void exactGeneratedCommittedReceiptSurvivesOnlyTheCurrentPreparedCaller(){var f=new FactoryFixtureImpl();var r=request();f.prepareResponse=prepared(r.actionId(),"BIND");f.commandResponse=committed(r);StepVerifier.create(caller(service(f).bind(r),"human-A")).assertNext(value->{assertEquals(GovernedPolicyCommandResponse.Status.COMMITTED,value.status());assertEquals(r.actionId(),value.actionId());assertEquals(DIGEST,value.intentDigest());assertNotNull(value.result());assertEquals(r.offerId(),value.result().offerId());assertEquals(r.acceptanceActionId(),value.result().acceptanceActionId());}).verifyComplete();assertEquals(2,f.sent.size());}
    @Test void knownCommitWithLostAuthorityKeepsOriginalIdentityButWithholdsTheReceipt(){var f=new FactoryFixtureImpl();var r=request();f.prepareResponse=prepared(r.actionId(),"BIND");f.commandResponse=committed(r);f.revokeAfterCommand=true;StepVerifier.create(caller(service(f).bind(r),"human-A")).assertNext(value->{assertEquals(GovernedPolicyCommandResponse.Status.COMMITTED_RESPONSE_UNAVAILABLE,value.status());assertEquals(r.actionId(),value.actionId());assertEquals(DIGEST,value.intentDigest());assertNull(value.result());}).verifyComplete();assertEquals(2,f.sent.size());}
}
